== spec/book.spec.sh
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\n' > "$t"
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 09:00 10:30 x >/dev/null || { echo "book failed"; fail=1; }
grep -q '^# room' "$t" && grep -q '^aoi.2026-01-05.09:00.10:30.x$' "$t" || { echo "booking not appended"; fail=1; }
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 10:00 11:00 y >/dev/null 2>&1; [ $? = 1 ] || { echo "overlap should exit 1"; fail=1; }
rm -f "$t"; exit $fail
== spec/list.spec.sh
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-02\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list sorted"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh 2026-01-02)" = '2026-01-02 10:00-11:00 aoi x' ] || { echo "list by date"; fail=1; }
rm -f "$t"; exit $fail
== spec/list_date.spec.sh
#!/bin/bash
fail=0
bash src/list.sh 2026/01/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(bash src/list.sh 2026/01/01 2>&1 >/dev/null)" = 'bad date: 2026/01/01 (expected YYYY-MM-DD)' ] || { echo "bad date message"; fail=1; }
exit $fail
== spec/slots.spec.sh
#!/bin/bash
. src/lib/slots.sh
fail=0
overlaps 600 660 630 700 || { echo "overlap: 10:00-11:00 vs 10:30-11:40"; fail=1; }
overlaps 600 720 630 650 || { echo "overlap: containment"; fail=1; }
! overlaps 600 660 700 760 || { echo "apart: 10:00-11:00 vs 11:40-12:40"; fail=1; }
[ "$(to_min 09:05)" = 545 ] || { echo "to_min 09:05"; fail=1; }
exit $fail
---
# room	date	start	end	who
aoi	2026-11-10	09:00	10:00	sato
kaede	2026-11-10	09:30	11:00	tanaka

